#include <stdio.h>
#include <stdlib.h>

typedef struct {
    long long x;
    int delta;
} Event;

int cmp(const void *a, const void *b) {
    const Event *ea = (const Event*)a;
    const Event *eb = (const Event*)b;
    if (ea->x < eb->x) return -1;
    if (ea->x > eb->x) return 1;
    if (ea->delta < eb->delta) return -1;
    if (ea->delta > eb->delta) return 1;
    return 0;
}

int main() {
    int N;
    scanf("%d", &N);

    long long *A = (long long*)malloc(N * sizeof(long long));
    for (int i = 0; i < N; i++) {
        scanf("%lld", &A[i]);
    }

    Event *ev = (Event*)malloc(2 * N * sizeof(Event));
    int m = 0;
    long long prev = 0;

    for (int i = 0; i < N; i++) {
        long long cur = A[i];
        if (cur > prev) {
            ev[m].x = prev;
            ev[m].delta = 1;
            m++;
            ev[m].x = cur;
            ev[m].delta = -1;
            m++;
        }
        prev = cur;
    }

    qsort(ev, m, sizeof(Event), cmp);

    int cur = 0, best = 0;
    for (int i = 0; i < m; i++) {
        cur += ev[i].delta;
        if (cur > best) best = cur;
    }

    printf("%d\n", best + 1);

    free(A);
    free(ev);
    return 0;
}
